from datetime import timedelta

def as_hms(time_str):
    if isinstance(time_str, str):
        h, m, s = map(int, time_str.split(':'))
        return timedelta(hours=h, minutes=m, seconds=s)
    return timedelta(seconds=time_str)

def format_hms(td):
